import functools

def min_diff(weights):
    total_sum = sum(weights)
    n = len(weights)

    @functools.lru_cache(None)
    def dp(i, s):
        if i == n:
            return abs(s - (total_sum - s))
        return min(dp(i + 1, s + weights[i]), dp(i + 1, s))

    return dp(0, 0)

