def min_difference(N, W):
    total_sum = sum(W)
    max_possible_sum = total_sum // 2
    dp = [[False] * (max_possible_sum + 1) for _ in range(N + 1)]

    # Initialize base case
    for i in range(N + 1):
        dp[i][0] = True

    # Fill the DP table
    for i in range(1, N + 1):
        for j in range(1, max_possible_sum + 1):
            if W[i - 1] <= j:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - W[i - 1]]
            else:
                dp[i][j] = dp[i - 1][j]

    # Find the maximum sum that can be achieved without exceeding half of the total sum
    for s in range(max_possible_sum, -1, -1):
        if dp[N][s]:
            break

    # Calculate the minimum absolute difference
    return abs(total_sum - 2 * s)

