def min_difference(N, W):
    total_sum = sum(W)
    dp = [False] * (total_sum + 1)
    dp[0] = True

    for w in W:
        for j in range(total_sum, w - 1, -1):
            dp[j] |= dp[j - w]

    min_diff = float('inf')
    for s1 in range(total_sum // 2 + 1):
        if dp[s1]:
            s2 = total_sum - s1
            min_diff = min(min_diff, abs(s1 - s2))

    return min_diff

