import sys

def min_partition_difference(N, weights):
    total_sum = sum(weights)
    target = total_sum // 2
    dp = {0}

    for weight in weights:
        new_dp = dp.copy()
        for s in dp:
            if s + weight <= target:
                new_dp.add(s + weight)
        dp = new_dp

    return min(abs(target - s) for s in dp)

