import sys
from typing import List

def min_partition_difference(weights: List[int]) -> int:
    total_sum = sum(weights)
    n = len(weights)

    @lru_cache(None)
    def can_partition(i: int, target: int) -> bool:
        if target == 0:
            return True
        if i == 0 or target < 0:
            return False
        return can_partition(i - 1, target) or can_partition(i - 1, target - weights[i - 1])

    min_diff = float('inf')
    for t in range(1, n):
        s1 = sum(weights[:t])
        s2 = total_sum - s1
        diff = abs(s1 - s2)
        if diff < min_diff:
            min_diff = diff

    return min_diff

